//! The C# rendering helpers every generator shares, including the one enum writer (README R6):
//! interop enums, the hotkey key and modifier enums and the IPC string enums all go through
//! [`enum_decl`] / [`enum_inline`], so the solution has one enum style.

use std::fmt::Write as _;

/// The header every output starts with. csbindgen's own header follows it in NativeMethods.g.cs.
pub fn header(module: &str, source: &str) -> String {
    format!(
        "// <auto-generated>\n// Generated by prisc_codegen (crates/prisc_codegen/src/{module}.rs) from {source}.\n// Do not edit. \
         Regenerate: cargo codegen\n// </auto-generated>\n"
    )
}

/// The first two lines every output's header carries; `orphans` keys on them.
pub const HEADER_PREFIX: &str = "// <auto-generated>\n// Generated by prisc_codegen ";

/// `dropped_perc` to `DroppedPerc`, `NO_SCREEN_PERMISSION` to `NoScreenPermission`: each part's
/// first letter upper case, the rest lower case.
pub fn pascal(name: &str) -> String {
    name.split('_')
        .filter(|part| !part.is_empty())
        .map(|part| part[..1].to_ascii_uppercase() + &part[1..].to_ascii_lowercase())
        .collect()
}

/// `dropped_perc` to `_droppedPerc`: a local that can never be a keyword or clash with `r`/`w`.
pub fn local(name: &str) -> String {
    let pascal = pascal(name);
    format!("_{}{}", pascal[..1].to_ascii_lowercase(), &pascal[1..])
}

/// A C# regular string literal's body: `\` and `"` escaped (every current input is printable).
pub fn escape(text: &str) -> String {
    text.replace('\\', "\\\\")
        .replace('"', "\\\"")
}

/// A complete C# regular string literal, every control character escaped.
pub fn string_literal(text: &str) -> String {
    let mut out = String::from("\"");
    for c in text.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\0' => out.push_str("\\0"),
            c if c.is_control() => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// A C# raw string literal (`"""..."""`), for golden JSON lines. Panics when the text cannot be
/// one (it contains `"""` or starts or ends with a quote).
pub fn raw_string_literal(text: &str) -> String {
    assert!(
        !text.contains("\"\"\"") && !text.starts_with('"') && !text.ends_with('"') && !text.contains('\n'),
        "{text} needs another C# literal form"
    );
    format!("\"\"\"{text}\"\"\"")
}

/// Doc text as XML doc content: `&`, `<` and `>` escaped, and Rust's `code` spans as `<c>code</c>`.
pub fn xml_text(text: &str) -> String {
    let escaped = text
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;");
    let mut out = String::new();
    let mut open = false;
    for c in escaped.chars() {
        if c == '`' {
            out.push_str(if open { "</c>" } else { "<c>" });
            open = !open;
        } else {
            out.push(c);
        }
    }
    if open {
        out.push_str("</c>");
    }
    out
}

/// A one-line `/// <summary>` for `text` at `indent`; nothing when `text` is empty.
pub fn summary(text: &str, indent: &str) -> String {
    if text.trim().is_empty() {
        return String::new();
    }
    format!("{indent}/// <summary>{}</summary>\n", xml_text(text.trim()))
}

/// The `///` doc lines of a syn item, trimmed and joined with single spaces.
pub fn doc_of(attrs: &[syn::Attribute]) -> String {
    let mut parts = Vec::new();
    for attr in attrs {
        if !attr.path().is_ident("doc") {
            continue;
        }
        if let syn::Meta::NameValue(nv) = &attr.meta {
            if let syn::Expr::Lit(syn::ExprLit {
                lit: syn::Lit::Str(s),
                ..
            }) = &nv.value
            {
                let line = s.value();
                let line = line.trim();
                if !line.is_empty() {
                    parts.push(line.to_string());
                }
            }
        }
    }
    parts.join(" ")
}

/// `0x3B97D2u`.
pub fn hex_u32(value: u32) -> String {
    format!("0x{value:06X}u")
}

/// A C# double literal that reads back as the same value.
pub fn double(value: f64) -> String {
    if value.is_finite() {
        let text = format!("{value:?}");
        if text.contains('.') || text.contains('e') {
            text
        } else {
            format!("{text}.0")
        }
    } else if value.is_nan() {
        "double.NaN".into()
    } else if value > 0.0 {
        "double.PositiveInfinity".into()
    } else {
        "double.NegativeInfinity".into()
    }
}

/// How an enum's doc comment is written.
pub enum Doc {
    /// Pre-formatted `///` line bodies (including any `<summary>` tags), one per line.
    Lines(Vec<String>),
    /// Plain text rendered as one `<summary>` line.
    Summary(String),
    None,
}

/// One enum member.
pub struct Member {
    pub name: String,
    /// The value text as written after `=`.
    pub value: String,
    pub doc: String,
}

/// One enum as a block:
///
/// ```text
///     /// <summary>...</summary>
///     [Flags]
///     public enum Name : uint
///     {
///         /// <summary>...</summary>
///         Member = 1,
///     }
/// ```
pub struct EnumDecl {
    pub name: String,
    /// `int`, `uint`, `byte`; `None` writes no base type.
    pub underlying: Option<String>,
    pub flags: bool,
    pub access: &'static str,
    pub doc: Doc,
    pub members: Vec<Member>,
}

/// Renders an [`EnumDecl`] at `indent` (no trailing blank line).
pub fn enum_decl(decl: &EnumDecl, indent: &str) -> String {
    let mut out = String::new();
    match &decl.doc {
        Doc::Lines(lines) => {
            for line in lines {
                let _ = writeln!(out, "{indent}/// {line}");
            }
        }
        Doc::Summary(text) => out.push_str(&summary(text, indent)),
        Doc::None => {}
    }
    if decl.flags {
        let _ = writeln!(out, "{indent}[Flags]");
    }
    let base = decl
        .underlying
        .as_ref()
        .map(|t| format!(" : {t}"))
        .unwrap_or_default();
    let _ = writeln!(out, "{indent}{} enum {}{base}", decl.access, decl.name);
    let _ = writeln!(out, "{indent}{{");
    for member in &decl.members {
        out.push_str(&summary(&member.doc, &format!("{indent}    ")));
        let _ = writeln!(out, "{indent}    {} = {},", member.name, member.value);
    }
    let _ = writeln!(out, "{indent}}}");
    out
}

/// A one-line enum with implicit values: `public enum Name { A, B }` (the IPC string enums,
/// whose `Unknown` default must stay 0).
pub fn enum_inline(name: &str, members: &[&str], indent: &str) -> String {
    format!("{indent}public enum {name} {{ {} }}\n", members.join(", "))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names() {
        assert_eq!(pascal("NO_SCREEN_PERMISSION"), "NoScreenPermission");
        assert_eq!(pascal("raw_code"), "RawCode");
        assert_eq!(local("dropped_perc"), "_droppedPerc");
    }

    #[test]
    fn literals() {
        assert_eq!(string_literal("a\"b\\c\n\u{1}"), "\"a\\\"b\\\\c\\n\\u0001\"");
        assert_eq!(escape("a\"\\"), "a\\\"\\\\");
        assert_eq!(raw_string_literal("{\"a\":1}"), "\"\"\"{\"a\":1}\"\"\"");
        assert_eq!(hex_u32(0x3B97D2), "0x3B97D2u");
        assert_eq!(double(0.18), "0.18");
        assert_eq!(double(3.0), "3.0");
        assert_eq!(xml_text("`a` < b & c"), "<c>a</c> &lt; b &amp; c");
    }

    #[test]
    fn enum_block_shape() {
        let decl = EnumDecl {
            name: "OverlayFlags".into(),
            underlying: Some("uint".into()),
            flags: true,
            access: "public",
            doc: Doc::Summary("Bit flags.".into()),
            members: vec![
                Member {
                    name: "None".into(),
                    value: "0".into(),
                    doc: String::new(),
                },
                Member {
                    name: "ClickThrough".into(),
                    value: "4".into(),
                    doc: "Mouse `events` pass.".into(),
                },
            ],
        };
        assert_eq!(
            enum_decl(&decl, "    "),
            "    /// <summary>Bit flags.</summary>\n    [Flags]\n    public enum OverlayFlags : uint\n    {\n        None = 0,\n        \
             /// <summary>Mouse <c>events</c> pass.</summary>\n        ClickThrough = 4,\n    }\n"
        );
        assert_eq!(
            enum_inline("JobResult", &["Unknown", "Ok"], "    "),
            "    public enum JobResult { Unknown, Ok }\n"
        );
    }
}
